CREATE OR REPLACE FUNCTION public.generate_rent_charges(_tenancy uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.tenancies; m date; d date; BEGIN SELECT * INTO t FROM public.tenancies WHERE id=_tenancy; IF NOT FOUND OR (auth.uid() IS NOT NULL AND NOT public.contract_party(_tenancy)) THEN RAISE EXCEPTION 'Contrato no disponible'; END IF; IF t.status NOT IN ('active','expiring') THEN RETURN; END IF; FOR m IN SELECT generate_series(date_trunc('month',t.start_date),date_trunc('month',least(coalesce(t.end_date,(CURRENT_DATE+interval '11 months')::date),(CURRENT_DATE+interval '11 months')::date)),interval '1 month')::date LOOP d:=greatest(m+(t.payment_day-1),t.start_date); IF t.end_date IS NULL OR d<=t.end_date THEN INSERT INTO public.rent_charges(tenancy_id,period,due_on,amount) VALUES(t.id,m,d,t.rent_amount) ON CONFLICT DO NOTHING; END IF; END LOOP; END; $$;
CREATE POLICY "Document path integrity" ON public.contract_documents AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.contract_owner(tenancy_id)) WITH CHECK(split_part(path,'/',1)=tenancy_id::text AND split_part(path,'/',2)=auth.uid()::text);
CREATE POLICY "Inventory file integrity" ON public.inventories AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(photo_path IS NULL OR (split_part(photo_path,'/',1)=tenancy_id::text AND split_part(photo_path,'/',2)=auth.uid()::text));
CREATE POLICY "Inventory updated file integrity" ON public.inventories AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.contract_owner(tenancy_id)) WITH CHECK(photo_path IS NULL OR (split_part(photo_path,'/',1)=tenancy_id::text AND split_part(photo_path,'/',2)=auth.uid()::text));
CREATE FUNCTION public.protect_message_edit() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.sender_id<>OLD.sender_id OR NEW.recipient_id<>OLD.recipient_id OR NEW.content<>OLD.content OR NEW.tenancy_id IS DISTINCT FROM OLD.tenancy_id OR NEW.created_at<>OLD.created_at THEN RAISE EXCEPTION 'Solo se permite marcar el mensaje como leído'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER protect_message_edit BEFORE UPDATE ON public.messages FOR EACH ROW EXECUTE FUNCTION public.protect_message_edit();
CREATE FUNCTION public.record_repair_comment_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t uuid; BEGIN SELECT tenancy_id INTO t FROM public.issues WHERE id=NEW.issue_id; IF t IS NOT NULL THEN INSERT INTO public.activity_log(tenancy_id,event,reference_id,actor_id) VALUES(t,'Comentario en reparación',NEW.id,NEW.author_id); END IF; RETURN NEW; END; $$;
CREATE TRIGGER repair_comment_activity AFTER INSERT ON public.issue_comments FOR EACH ROW EXECUTE FUNCTION public.record_repair_comment_activity();
CREATE FUNCTION public.inventory_immutable_acceptance() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.agreed_at IS NOT NULL THEN RAISE EXCEPTION 'El inventario aceptado es inmutable'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER inventory_immutable_acceptance BEFORE UPDATE ON public.inventories FOR EACH ROW EXECUTE FUNCTION public.inventory_immutable_acceptance();